def carre(n):
    return n * n

print(carre(7))

def est_pair(n):
    return n % 2 == 0

print(est_pair(4), est_pair(7))

def cout(minutes):
    total = minutes * 25
    if minutes >= 60:
        total = int(total * 0.9)
    return total

print(cout(30), cout(90))
